from course_model import *
c=chapter('dom','JavaScript · pagina devine interactivă','DOM real: citești câmpuri, reacționezi la clic și construiești filtrele.','resurse/js/produse.js, produse-cos.js, tema.js, schimba_tema.js, cookies.js','cursor')
def D(id,title,idea,code,fixture,tests,question,actions=None,prompt=None):
 lesson(c,id,title,idea,code,idea,question,dom(prompt or 'Scrie codul din exemplu și verifică efectul asupra paginii.',code,fixture,tests,actions))
D('dom-select','Găsește un element','document reprezintă pagina. querySelector primește un selector CSS și întoarce primul element potrivit sau null. getElementById primește doar id-ul, fără #.',
 'const heading = document.querySelector("#welcome");\nheading.textContent = "Welcome";', '<h1 id="welcome">Old title</h1>',[exact('#welcome','Welcome')],q('Ce primește querySelector?','Un selector CSS','Numai un număr','O interogare SQL'))
D('dom-text','Text simplu și HTML','textContent inserează text. innerHTML interpretează markup. Pentru date pe care vrei să le afișezi ca text, textContent evită interpretarea lor ca taguri.',
 'document.querySelector("#message").textContent = "<strong>Cake</strong>";','<p id="message"></p>',[exact('#message','<strong>Cake</strong>'),absent('#message strong')],q('Ce inserează literalmente textul cu taguri?','textContent','innerHTML','outerHTML cu același efect'))
D('dom-collection','Mai multe elemente','querySelectorAll întoarce o colecție NodeList. O poți parcurge cu for...of sau transforma cu Array.from. getElementsByClassName întoarce o colecție live, care se poate schimba odată cu DOM-ul.',
 'for (const card of document.querySelectorAll(".product-card")) {\n  card.classList.add("ready");\n}', '<article class="product-card">Cake</article><article class="product-card">Tea</article>',[count('.product-card.ready',2)],q('Ce întoarce querySelectorAll?','O colecție de elemente','Un șir JSON obligatoriu','Întotdeauna primul element'))
D('dom-class','Adaugă și elimină clase','classList.add, remove și toggle modifică lista de clase fără să ștergi celelalte clase ale elementului. toggle întoarce dacă acea clasă este prezentă după operație.',
 'const card = document.querySelector("#card");\ncard.classList.remove("hidden");\ncard.classList.add("active");', '<article id="card" class="product-card hidden">Cake</article>',[count('#card.product-card.active'),absent('#card.hidden')],q('Ce face classList.toggle?','Adaugă sau elimină clasa','Șterge întregul element','Schimbă automat fișierul CSS'))
D('dom-click','Reacționează la clic','addEventListener leagă o funcție de un eveniment. Transmiți funcția, nu rezultatul apelului ei. onclick este o alternativă, dar o reasignare poate înlocui handler-ul anterior.',
 'document.querySelector("#showButton").addEventListener("click", () => {\n  document.querySelector("#message").textContent = "Ready";\n});', '<button id="showButton" type="button">Show</button><p id="message"></p>',[exact('#message','Ready')],q('Ce transmiți ca al doilea argument la addEventListener?','O funcție','Rezultatul obligatoriu al funcției','Un selector SQL'),[dict(type='click',selector='#showButton')])
D('dom-value','Citește un câmp','value este valoarea unui input. Chiar și câmpurile numerice pot oferi text prin value. Folosește trim și conversie când ai nevoie de numere.',
 'document.querySelector("#showButton").addEventListener("click", () => {\n  document.querySelector("#message").textContent = document.querySelector("#nameInput").value.trim();\n});', '<input id="nameInput"><button id="showButton">Show</button><p id="message"></p>',[exact('#message','Cake')],q('Ce proprietate citește textul unui input?','value','textContent al input-ului','src'),[dict(type='fill',selector='#nameInput',value=' Cake '),dict(type='click',selector='#showButton')])
D('dom-input-event','Actualizează valoarea unui range','Evenimentul input apare pe măsură ce utilizatorul schimbă valoarea. change apare la confirmarea schimbării, în funcție de control. Pentru o etichetă live alegem input.',
 'const slider = document.querySelector("#minPrice");\nslider.addEventListener("input", () => {\n  document.querySelector("#priceLabel").textContent = slider.value;\n});', '<input id="minPrice" type="range" min="0" max="100"><output id="priceLabel"></output>',[exact('#priceLabel','25')],q('Ce eveniment alegem pentru actualizare live a range-ului?','input','load pentru fiecare pixel','submit'),[dict(type='fill',selector='#minPrice',value='25',event='input')])
D('dom-checked','Citește selecția checkbox-ului','checked este boolean și arată selecția curentă. Atributul HTML checked descrie starea inițială; nu este același lucru cu proprietatea curentă după interacțiune.',
 'document.querySelector("#cartChoice").addEventListener("change", event => {\n  document.querySelector("#message").textContent = event.target.checked ? "Selected" : "Not selected";\n});', '<input id="cartChoice" type="checkbox"><p id="message"></p>',[exact('#message','Selected')],q('Ce proprietate arată selecția curentă?','checked','value obligatoriu true','getAttribute("checked") în orice moment'),[dict(type='check',selector='#cartChoice',checked=True)])
D('dom-create','Creează și atașează un element','createElement construiește un element care nu este încă în pagină. append îl atașează la un părinte. textContent îi setează textul.',
 'const item = document.createElement("li");\nitem.textContent = "Cake";\ndocument.querySelector("#products").append(item);', '<ul id="products"></ul>',[exact('#products > li','Cake')],q('createElement afișează singur elementul?','Nu; trebuie atașat','Da, automat în body','Doar dacă este li'))
D('dom-remove','Elimină un element','remove elimină elementul din DOM. Verifică dacă selectorul a găsit ceva înainte să apelezi metode pe el.',
 'const notice = document.querySelector("#notice");\nif (notice) { notice.remove(); }', '<p id="notice">Temporary</p><p id="keep">Keep</p>',[absent('#notice'),exact('#keep','Keep')],q('Ce întoarce querySelector când nu găsește nimic?','null','Un element gol obligatoriu','false în toate cazurile'))
D('dom-dataset','Date pe elemente','Atributele data-* pot păstra date asociate unui card. data-price se citește cu element.dataset.price și este text; convertește explicit la număr.',
 'const card = document.querySelector(".product-card");\ndocument.querySelector("#total").textContent = String(Number(card.dataset.price) * 2);', '<article class="product-card" data-price="12.5">Cake</article><output id="total"></output>',[exact('#total','25')],q('Ce tip este dataset.price?','string','number garantat','boolean'),'')
D('dom-filter','Filtrează carduri după nume','Separă citirea filtrului de parcurgerea cardurilor. Normalizează ambele texte. hidden ascunde un card fără să îl ștergi; resetarea îl poate arăta din nou.',
 'document.querySelector("#filterButton").addEventListener("click", () => {\n  const query = document.querySelector("#searchName").value.trim().toLowerCase();\n  for (const card of document.querySelectorAll(".product-card")) {\n    card.hidden = !card.dataset.name.toLowerCase().startsWith(query);\n  }\n});', '<input id="searchName"><button id="filterButton">Filter</button><article class="product-card" data-name="Cake">Cake</article><article class="product-card" data-name="Tea">Tea</article>',[count('.product-card:not([hidden])',1),attr('.product-card:not([hidden])','data-name','Cake')],q('De ce normalizăm ambele texte?','Pentru comparație independentă de registru','Pentru a sorta automat prețul','Pentru a modifica baza SQL'),[dict(type='fill',selector='#searchName',value='CA'),dict(type='click',selector='#filterButton')])
D('dom-reset','Resetează toate filtrele','Resetarea trebuie să readucă atât valorile controalelor, cât și vizibilitatea produselor. Nu reseta doar câmpul text și lăsa filtrarea veche activă.',
 'document.querySelector("#resetButton").addEventListener("click", () => {\n  document.querySelector("#searchName").value = "";\n  for (const card of document.querySelectorAll(".product-card")) { card.hidden = false; }\n});', '<input id="searchName" value="Cake"><button id="resetButton">Reset</button><article class="product-card" hidden>Cake</article>',[dict(kind='value',selector='#searchName',value='',label='Câmp gol'),absent('.product-card[hidden]')],q('Ce trebuie resetat pe lângă câmpuri?','Efectul filtrării asupra cardurilor','Doar culoarea titlului','Numele fișierului'),[dict(type='click',selector='#resetButton')])
D('dom-sort','Reordonează elementele DOM','Colecția devine Array prin Array.from. Sortezi referințele, apoi append mută elementele existente în ordinea nouă; nu le clonează.',
 'const list = document.querySelector("#products");\nconst cards = Array.from(list.children);\ncards.sort((a, b) => Number(a.dataset.price) - Number(b.dataset.price));\nfor (const card of cards) { list.append(card); }', '<div id="products"><article data-price="20">Cake</article><article data-price="5">Tea</article></div>',[exact('#products > article:first-child','Tea'),exact('#products > article:last-child','Cake')],q('Ce face append pentru un nod deja atașat?','Îl mută','Îl clonează obligatoriu','Aruncă mereu eroare'))
D('dom-keyboard','Evenimente de tastatură','Un KeyboardEvent oferă key și modificatori precum altKey. În proiect Alt+C poate calcula totalul produselor vizibile. Oferă și un buton pentru aceeași acțiune, ca să nu depinzi numai de scurtătură.',
 'document.addEventListener("keydown", event => {\n  if (event.altKey && event.key.toLowerCase() === "c") {\n    document.querySelector("#message").textContent = "Calculate total";\n  }\n});', '<p id="message"></p>',[exact('#message','Calculate total')],q('Ce proprietate arată apăsarea Alt?','altKey','keyAltCode','ctrlKey'),[dict(type='key',key='c',altKey=True)])
D('dom-timeout','O acțiune mai târziu','setTimeout planifică un callback după o întârziere minimă. Nu oprește sincron tot programul și nu garantează o execuție la o milisecundă exactă.',
 'setTimeout(() => {\n  document.querySelector("#message").textContent = "Ready";\n}, 20);', '<p id="message">Waiting</p>',[exact('#message','Ready')],q('setTimeout blochează programul până expiră timpul?','Nu','Da, întotdeauna','Numai în HTML'))
D('dom-ready','DOMContentLoaded și load','DOMContentLoaded apare când documentul a fost parsată și scripturile relevante sunt tratate; load așteaptă și resursele asociate. Un script cu defer poate accesa DOM-ul după parsare.',
 'const heading = document.querySelector("#welcome");\nheading.textContent = "DOM ready";', '<h1 id="welcome"></h1>',[exact('#welcome','DOM ready')],q('Ce eveniment este potrivit când ai nevoie de structura DOM?','DOMContentLoaded','mouseover obligatoriu','change pe document'),'')
D('dom-theme','Comută tema printr-o clasă','Tema se poate controla printr-o clasă pe body și variabile CSS. Nu rescrie fiecare culoare în JavaScript. Toggle schimbă doar starea, CSS decide aspectul.',
 'document.querySelector("#themeButton").addEventListener("click", () => {\n  document.body.classList.toggle("dark");\n});', '<button id="themeButton">Theme</button>',[count('body.dark')],q('Unde definim culorile temei?','În CSS','În textContent-ul fiecărui buton','Într-un atribut SQL'),[dict(type='click',selector='#themeButton')])

storage=chapter('storage','Stare în browser · coș și cookies','Serializezi date, restaurezi selecții și separi preferințele de datele serverului.','resurse/js/produse-cos.js, tema.js, schimba_tema.js și cookies.js','save')
lesson(storage,'storage-model','localStorage păstrează texte','localStorage oferă getItem, setItem și removeItem. Datele aparțin originii site-ului. Pentru obiecte folosești JSON.stringify la salvare și JSON.parse la citire.',
 'localStorage.setItem("theme", "dark");\nconst theme = localStorage.getItem("theme");', 'În laboratorul DOM izolat nu folosim stocarea personală a browserului. Exersăm formatul de date prin funcții, apoi legăm localStorage în proiectul real.',q('Ce tip păstrează localStorage ca valoare?','Text','Orice obiect fără serializare','O conexiune PostgreSQL'),js('Returnează textul JSON pentru input.','function solve(input) { return JSON.stringify(input); }',[({'theme':'dark'},'{"theme":"dark"}'),([], '[]')] ))
lesson(storage,'storage-restore','Restaurează o valoare opțională','getItem poate întoarce null când cheia lipsește. Folosește un fallback și tratează JSON corupt când datele provin dintr-o salvare anterioară.',
 'const saved = localStorage.getItem("cart");\nconst cart = saved ? JSON.parse(saved) : [];', 'O salvare veche poate avea alt format. În proiect verificăm tipul și revenim la un coș gol dacă textul nu poate fi parsată.',q('Ce returnează getItem pentru o cheie lipsă?','null','[] automat','0 obligatoriu'),js('Primești text JSON sau null. Returnează vectorul parsată; pentru null, JSON invalid ori alt tip returnează [].','function solve(input) { try { const value = input ? JSON.parse(input) : []; return Array.isArray(value) ? value : []; } catch { return []; } }',[(None,[]),('[1,2]',[1,2]),('{bad}',[]),('{}',[])]))
lesson(storage,'cart-add','Adaugă fără duplicate','Coșul din exemplu păstrează identificatori de produse. Un checkbox bifat adaugă un id; repetarea aceleiași selecții nu trebuie să dubleze produsul.',
 'const cart = ["1", "2"];\nif (!cart.includes("3")) { cart.push("3"); }', 'În exercițiu lucrăm pe o copie; în site salvăm apoi rezultatul în localStorage.',q('Ce identifică produsul selectat?','Id-ul produsului','Poziția lui vizuală după sortare','Culoarea cardului'),js('Primești {cart, id}. Returnează o copie cu id adăugat dacă lipsește.','function solve(input) { return input.cart.includes(input.id) ? [...input.cart] : [...input.cart, input.id]; }',[({'cart':['1'],'id':'2'},['1','2']),({'cart':['1'],'id':'1'},['1'])]))
lesson(storage,'cart-remove','Elimină produsul debifat','La debifare eliminăm id-ul corespunzător, nu ultimul produs din coș. filter produce simplu o listă fără acel id.',
 'const nextCart = cart.filter(id => id !== removedId);', 'Sortarea vizuală a produselor nu schimbă identitatea lor. Folosește id-uri stabile.',q('Cum identificăm ce trebuie eliminat?','Prin id','Prin ultimul element întotdeauna','Prin titlul paginii'),js('Primești {cart, id}. Returnează coșul fără id.','function solve(input) { return input.cart.filter(id => id !== input.id); }',[({'cart':['1','2'],'id':'1'},['2']),({'cart':[],'id':'1'},[])]))
lesson(storage,'cart-total','Totalul produselor vizibile','Filtrarea ascunde carduri; calculul trebuie să includă numai produsele vizibile. În site citim starea și prețul fiecărui card și afișăm totalul.',
 'const total = products.filter(product => product.visible).reduce((sum, product) => sum + product.price, 0);', 'Poți exprima aceeași regulă într-o funcție independentă de DOM, mai ușor de testat.',q('Ce produse intră în totalul cerut?','Cele vizibile','Toate indiferent de filtru','Doar cel mai scump'),js('Returnează suma price pentru obiectele cu visible true.','function solve(input) { return input.filter(product => product.visible).reduce((total, product) => total + product.price, 0); }',[([{'price':10,'visible':True},{'price':20,'visible':False}],10),([],0)]))
lesson(storage,'cookie-read','Citește o pereche din cookie-uri','document.cookie reprezintă perechi separate prin ;. Nu căuta doar un prefix arbitrar: separă numele de valoare și elimină spațiile de la capete.',
 'const pairs = document.cookie.split(";").map(part => part.trim());', 'O valoare poate fi codificată cu encodeURIComponent. În exercițiu primești textul direct, fără a modifica cookie-urile calculatorului.',q('Ce separă perechile din document.cookie?',';','Doar spațiul','Caracterul #'),js('Primești {cookies, name}. Returnează valoarea decodificată a cookie-ului sau null.','function solve(input) { const pair = input.cookies.split(";").map(part => part.trim()).find(part => part.startsWith(input.name + "=")); return pair ? decodeURIComponent(pair.slice(input.name.length + 1)) : null; }',[({'cookies':'theme=dark; consent=yes','name':'consent'},'yes'),({'cookies':'a=1','name':'b'},None),({'cookies':'name=A%20B','name':'name'},'A B')]))
lesson(storage,'cookie-write','Expirare, cale și ștergere','Un cookie poate avea expires sau max-age și o cale. Pentru ștergere trebuie să folosești aceeași cale relevantă și o expirare trecută, de exemplu Max-Age=0.',
 'document.cookie = "consent=yes; Max-Age=3600; Path=/; SameSite=Lax";\ndocument.cookie = "consent=; Max-Age=0; Path=/; SameSite=Lax";', 'Un banner care memorează o preferință în proiect este un exemplu tehnic, nu o confirmare automată că orice site respectă toate obligațiile privind cookies.',q('Ce valoare Max-Age șterge cookie-ul?','0','3600','-value ca text obligatoriu'),text('Scrie doar valoarea Max-Age care șterge cookie-ul.','0'))
